-- Apply once after 001_schema.sql and 002_templates.sql. Prefer bin/migrate.php.
ALTER TABLE users ADD COLUMN google_sub VARCHAR(255) NULL UNIQUE, ADD COLUMN plan VARCHAR(20) NOT NULL DEFAULT 'free', ADD COLUMN plan_until DATETIME NULL, ADD COLUMN email_verified_at DATETIME NULL;
ALTER TABLE brands ADD COLUMN archived TINYINT NOT NULL DEFAULT 0;
ALTER TABLE templates ADD COLUMN category VARCHAR(100) NOT NULL DEFAULT 'General', ADD COLUMN access_tier VARCHAR(20) NOT NULL DEFAULT 'free', ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'published';
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,last_seen DATETIME NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS otp_challenges (id CHAR(64) PRIMARY KEY,email VARCHAR(255) NOT NULL,code_hash CHAR(64) NOT NULL,purpose VARCHAR(20) NOT NULL,attempts INT NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL,consumed_at DATETIME NULL,created_at DATETIME NOT NULL,INDEX(email,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_settings (setting_key VARCHAR(100) PRIMARY KEY,value_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,event VARCHAR(100) NOT NULL,detail VARCHAR(1000) NOT NULL DEFAULT '',created_at DATETIME NOT NULL,INDEX(created_at),INDEX(user_id,event,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS visit_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,visitor_hash CHAR(64) NOT NULL,path VARCHAR(80) NOT NULL,source VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL,INDEX(created_at),INDEX(visitor_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS template_files (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,template_id BIGINT UNSIGNED NOT NULL,role VARCHAR(20) NOT NULL,original_filename VARCHAR(255) NOT NULL,storage_path VARCHAR(255) NOT NULL,mime_type VARCHAR(50) NOT NULL,file_size INT UNSIGNED NOT NULL,width INT NOT NULL,height INT NOT NULL,FOREIGN KEY(template_id) REFERENCES templates(id) ON DELETE CASCADE,INDEX(template_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
